// Generated by vibes-espmatter – scenes: a named set of lights and how each should be (on/off,
// brightness, color temperature), switched all at once ("Movie night", "Good night").
//
// Everyone creates scenes on the user dashboard from the lights they may control
// (mesp_matter_allows); the owner (and admins) edit and delete them. An admin can share a scene
// with other users on the admin dashboard: they may then run it – all of its lights, sharing is
// the admin's decision – but not change it. The owner only switches the lights they may still
// control, so taking a light away from someone also takes it out of their scenes.
#include "espm_config.h"
#include "espm_matter.h"
#include "espm_web.h"

#include <cstring>
#include <esp_log.h>
#include <freertos/FreeRTOS.h>
#include <freertos/semphr.h>
#include <nvs.h>

#include <esp_matter.h>
#include <esp_matter_controller_cluster_command.h>

#include <app-common/zap-generated/cluster-objects.h>

static const char *TAG = "mesp_scenes";

using namespace esp_matter;
using namespace chip::app::Clusters;

#define MAX_SCENES 16
#define MAX_SCENE_LIGHTS 12
/** Shares over all scenes (scene × user). */
#define MAX_SHARES 48
/** A short transition (1/10 s) instead of a hard switch. */
#define TRANSITION_TENTHS 5

// Stored in NVS as is – only append, never reorder.
struct scene_light_t {
    uint64_t node;
    uint16_t ep;
    uint8_t on;
    uint8_t level;   // 1–254, 0 = leave the brightness
    uint16_t mireds; // 0 = leave the color temperature
    uint16_t reserved;
};

struct scene_rec_t {
    uint16_t id;
    uint8_t count;
    uint8_t reserved;
    char name[24];
    char owner[24];
    scene_light_t lights[MAX_SCENE_LIGHTS];
};
static_assert(sizeof(scene_rec_t) == 248, "scene_rec_t is stored in NVS: its size must not change");

struct share_t {
    uint16_t scene;
    char user[24];
    uint8_t reserved[2];
};
static_assert(sizeof(share_t) == 28, "share_t is stored in NVS: its size must not change");

static scene_rec_t s_scenes[MAX_SCENES];
static size_t s_count = 0;
static share_t s_shares[MAX_SHARES];
static size_t s_share_count = 0;
static uint16_t s_next_id = 1;
static SemaphoreHandle_t s_mutex;

namespace {
struct Lock {
    Lock() { xSemaphoreTakeRecursive(s_mutex, portMAX_DELAY); }
    ~Lock() { xSemaphoreGiveRecursive(s_mutex); }
};
} // namespace

// ---------------------------------------------------------------------------------------------
// Persistence
// ---------------------------------------------------------------------------------------------

static void save()
{
    nvs_handle_t h;
    if (nvs_open("mesp_scenes", NVS_READWRITE, &h) != ESP_OK) return;
    nvs_set_blob(h, "scenes", s_scenes, s_count * sizeof(scene_rec_t));
    nvs_set_blob(h, "shares", s_shares, s_share_count * sizeof(share_t));
    nvs_commit(h);
    nvs_close(h);
}

static void load()
{
    nvs_handle_t h;
    if (nvs_open("mesp_scenes", NVS_READONLY, &h) != ESP_OK) return;
    size_t len = sizeof(s_scenes);
    if (nvs_get_blob(h, "scenes", s_scenes, &len) == ESP_OK) s_count = len / sizeof(scene_rec_t);
    len = sizeof(s_shares);
    if (nvs_get_blob(h, "shares", s_shares, &len) == ESP_OK) s_share_count = len / sizeof(share_t);
    nvs_close(h);
    for (size_t i = 0; i < s_count; i++)
        if (s_scenes[i].id >= s_next_id) s_next_id = s_scenes[i].id + 1;
    ESP_LOGI(TAG, "Loaded %u scenes, %u shares", (unsigned)s_count, (unsigned)s_share_count);
}

// ---------------------------------------------------------------------------------------------
// Scenes and shares
// ---------------------------------------------------------------------------------------------

static int index_of(uint16_t id)
{
    for (size_t i = 0; i < s_count; i++)
        if (s_scenes[i].id == id) return i;
    return -1;
}

static bool shared_with(uint16_t scene, const char *user)
{
    for (size_t i = 0; i < s_share_count; i++)
        if (s_shares[i].scene == scene && strcmp(s_shares[i].user, user) == 0) return true;
    return false;
}

/** Drop the shares `drop` picks; true if any. */
template <typename F> static bool drop_shares(F drop)
{
    size_t kept = 0;
    for (size_t i = 0; i < s_share_count; i++)
        if (!drop(s_shares[i])) s_shares[kept++] = s_shares[i];
    bool changed = kept != s_share_count;
    s_share_count = kept;
    return changed;
}

static bool is_owner(const mesp_session_t &session, const scene_rec_t &s)
{
    return strcmp(s.owner, session.user) == 0;
}

/** Sees and runs it: owner, the users it's shared with, admins. */
static bool can_run(const mesp_session_t &session, const scene_rec_t &s)
{
    return session.role == MESP_ROLE_ADMIN || is_owner(session, s) || shared_with(s.id, session.user);
}

/** Changes and deletes it: owner and admins. */
static bool can_edit(const mesp_session_t &session, const scene_rec_t &s)
{
    return session.role == MESP_ROLE_ADMIN || is_owner(session, s);
}

static void delete_at(size_t idx)
{
    const uint16_t id = s_scenes[idx].id;
    for (size_t i = idx; i + 1 < s_count; i++) s_scenes[i] = s_scenes[i + 1];
    s_count--;
    drop_shares([id](const share_t &sh) { return sh.scene == id; });
}

/** A node left the fabric: its lights leave the scenes. */
static void node_removed(uint64_t node_id)
{
    Lock lock;
    bool changed = false;
    for (size_t i = 0; i < s_count; i++) {
        scene_rec_t &s = s_scenes[i];
        uint8_t kept = 0;
        for (uint8_t l = 0; l < s.count; l++)
            if (s.lights[l].node != node_id) s.lights[kept++] = s.lights[l];
        changed |= kept != s.count;
        s.count = kept;
    }
    if (changed) save();
}

/** A deleted user's scenes go with them, and so do the scenes shared with them. */
static void user_removed(const char *user)
{
    Lock lock;
    bool changed = drop_shares([user](const share_t &sh) { return strcmp(sh.user, user) == 0; });
    for (size_t i = s_count; i-- > 0;) {
        if (strcmp(s_scenes[i].owner, user) != 0) continue;
        delete_at(i);
        changed = true;
    }
    if (changed) save();
}

// ---------------------------------------------------------------------------------------------
// Running scenes
// ---------------------------------------------------------------------------------------------

/** Must hold the CHIP stack lock. */
static void invoke(const scene_light_t &l, uint32_t cluster, uint32_t command, const char *data)
{
    esp_err_t err = controller::send_invoke_cluster_command(l.node, l.ep, cluster, command, data);
    if (err != ESP_OK) {
        ESP_LOGW(TAG, "Command 0x%lx/0x%lx to node 0x%llx/%u failed: %s", (unsigned long)cluster,
                 (unsigned long)command, (unsigned long long)l.node, l.ep, esp_err_to_name(err));
    }
}

/** Must hold the CHIP stack lock. */
static void apply(const scene_light_t &l)
{
    if (!l.on) {
        invoke(l, OnOff::Id, OnOff::Commands::Off::Id, nullptr);
        return;
    }
    char data[72];
    // Also while off (ExecuteIfOff), so the light comes on in the right color; lights that ignore
    // it get it again once they're on.
    auto color = [&] {
        if (!l.mireds) return;
        snprintf(data, sizeof(data), "{\"0:U16\":%u,\"1:U16\":%u,\"2:U8\":1,\"3:U8\":1}", l.mireds, TRANSITION_TENTHS);
        invoke(l, ColorControl::Id, ColorControl::Commands::MoveToColorTemperature::Id, data);
    };
    color();
    if (l.level) {
        snprintf(data, sizeof(data), "{\"0:U8\":%u,\"1:U16\":%u,\"2:U8\":0,\"3:U8\":0}", l.level, TRANSITION_TENTHS);
        invoke(l, LevelControl::Id, LevelControl::Commands::MoveToLevelWithOnOff::Id, data);
    } else {
        invoke(l, OnOff::Id, OnOff::Commands::On::Id, nullptr);
    }
    color();
}

// ---------------------------------------------------------------------------------------------
// Web API
// ---------------------------------------------------------------------------------------------

void mesp_scenes_init()
{
    s_mutex = xSemaphoreCreateRecursiveMutex();
    load();
    mesp_matter_on_node_removed(node_removed);
    mesp_web_on_user_removed(user_removed);
}

static esp_err_t scenes_get(httpd_req_t *req)
{
    mesp_session_t session;
    if (!mesp_web_require(req, MESP_ROLE_USER, &session)) return ESP_OK;
    Json j;
    {
        Lock lock;
        j.obj().key("max").num(MAX_SCENES).key("maxLights").num(MAX_SCENE_LIGHTS).key("count").num(s_count);
        j.key("scenes").arr();
        for (size_t i = 0; i < s_count; i++) {
            const scene_rec_t &s = s_scenes[i];
            if (!can_run(session, s)) continue;
            j.obj().key("id").num(s.id).key("name").str(s.name).key("owner").str(s.owner);
            // Whom it's shared with: only for those who may change it.
            if (can_edit(session, s)) {
                j.key("shared").arr();
                for (size_t k = 0; k < s_share_count; k++)
                    if (s_shares[k].scene == s.id) j.str(s_shares[k].user);
                j.end_arr();
            }
            j.key("lights").arr();
            for (uint8_t l = 0; l < s.count; l++) {
                const scene_light_t &sl = s.lights[l];
                j.obj().key("node").unum(sl.node).key("endpoint").num(sl.ep).key("on").boolean(sl.on);
                j.key("level").num(sl.level).key("mireds").num(sl.mireds).end_obj();
            }
            j.end_arr().end_obj();
        }
        j.end_arr().end_obj();
    }
    return mesp_web_send_json(req, j.out());
}

/** Read a number field "a:b" of `item` from `pos`; false if it isn't one. */
static bool next_num(const std::string &item, size_t &pos, uint64_t &out)
{
    if (pos > item.size()) return false;
    size_t end = item.find(':', pos);
    if (end == std::string::npos) end = item.size();
    bool ok = mesp_parse_u64(item.substr(pos, end - pos), out);
    pos = end + 1;
    return ok;
}

/** "0x1:1:1:200:370,0x2:1:0:0:0" (node:endpoint:on:level:mireds) → the lights of a scene. */
static const char *parse_lights(const std::string &list, scene_rec_t &s)
{
    s.count = 0;
    size_t pos = 0;
    while (pos < list.size()) {
        size_t end = list.find(',', pos);
        if (end == std::string::npos) end = list.size();
        const std::string item = list.substr(pos, end - pos);
        pos = end + 1;
        if (s.count >= MAX_SCENE_LIGHTS) return "too many lights";
        uint64_t node, ep, on, level, mireds;
        size_t p = 0;
        if (!next_num(item, p, node) || !next_num(item, p, ep) || !next_num(item, p, on) ||
            !next_num(item, p, level) || !next_num(item, p, mireds) || p <= item.size()) {
            return "invalid light list";
        }
        if (!node || ep > 0xfffe || on > 1) return "invalid light";
        if (level > 254) return "invalid brightness";
        if (mireds && (mireds < 50 || mireds > 1000)) return "invalid color temperature";
        for (uint8_t i = 0; i < s.count; i++)
            if (s.lights[i].node == node && s.lights[i].ep == ep) return "a light is in the list twice";
        s.lights[s.count++] = {node, (uint16_t)ep, (uint8_t)on, (uint8_t)level, (uint16_t)mireds, 0};
    }
    return nullptr;
}

/** Read the scene fields of a request into `s` (missing fields keep their value). */
static const char *parse_scene(const std::string &body, const mesp_session_t &session, scene_rec_t &s)
{
    std::string v;
    if (mesp_web_param(body, "name", v)) {
        if (v.empty() || v.size() >= sizeof(s.name)) return "name: 1–23 characters";
        strlcpy(s.name, v.c_str(), sizeof(s.name));
    }
    if (mesp_web_param(body, "lights", v)) {
        if (const char *err = parse_lights(v, s)) return err;
        for (uint8_t i = 0; i < s.count; i++)
            if (!mesp_matter_allows(session, s.lights[i].node, s.lights[i].ep)) return "not allowed for this light";
    }
    if (!s.name[0]) return "a scene needs a name";
    return nullptr;
}

/** "anna,ben" → the shares of scene `id` (replacing its old ones). Must hold the lock. */
static const char *set_shares(uint16_t id, const char *owner, const std::string &list)
{
    share_t next[MAX_SHARES];
    size_t n = 0;
    size_t pos = 0;
    while (pos < list.size()) {
        size_t end = list.find(',', pos);
        if (end == std::string::npos) end = list.size();
        const std::string user = list.substr(pos, end - pos);
        pos = end + 1;
        if (user.empty() || user.size() >= sizeof(share_t::user)) return "invalid user name";
        if (user == owner) continue; // it's theirs anyway
        bool dup = false;
        for (size_t i = 0; i < n; i++) dup |= user == next[i].user;
        if (dup) continue;
        if (n >= MAX_SHARES) return "too many shares";
        next[n] = {};
        next[n].scene = id;
        strlcpy(next[n].user, user.c_str(), sizeof(next[n].user));
        n++;
    }
    size_t others = 0;
    for (size_t i = 0; i < s_share_count; i++) others += s_shares[i].scene != id;
    if (others + n > MAX_SHARES) return "too many shares";
    drop_shares([id](const share_t &sh) { return sh.scene == id; });
    for (size_t i = 0; i < n; i++) s_shares[s_share_count++] = next[i];
    return nullptr;
}

static esp_err_t scenes_post(httpd_req_t *req)
{
    mesp_session_t session;
    if (!mesp_web_require(req, MESP_ROLE_USER, &session)) return ESP_OK;
    std::string body, op, id_str;
    if (!mesp_web_read_body(req, body)) return ESP_OK;
    mesp_web_param(body, "op", op);
    mesp_web_param(body, "id", id_str);
    uint64_t id;

    if (op == "run") {
        // Copy the lights first: never wait for the CHIP stack while holding our lock.
        scene_light_t lights[MAX_SCENE_LIGHTS];
        size_t n = 0;
        char name[sizeof(scene_rec_t::name)];
        {
            Lock lock;
            int idx = mesp_parse_u64(id_str, id) ? index_of(id) : -1;
            if (idx < 0 || !can_run(session, s_scenes[idx])) {
                return mesp_web_send_error(req, "404 Not Found", "unknown scene");
            }
            const scene_rec_t &s = s_scenes[idx];
            // Shared by an admin: all of it. Otherwise only the lights the caller may (still) control.
            const bool all = shared_with(s.id, session.user);
            for (uint8_t l = 0; l < s.count; l++)
                if (all || mesp_matter_allows(session, s.lights[l].node, s.lights[l].ep)) lights[n++] = s.lights[l];
            strlcpy(name, s.name, sizeof(name));
        }
        ESP_LOGI(TAG, "Scene \"%s\" by %s: %u lights", name, session.user, (unsigned)n);
        esp_matter::lock::ScopedChipStackLock chip_lock(portMAX_DELAY);
        for (size_t i = 0; i < n; i++) apply(lights[i]);
        return mesp_web_send_json(req, "{\"ok\":true}");
    }

    Lock lock;
    if (op == "add") {
        if (s_count >= MAX_SCENES) return mesp_web_send_error(req, "409 Conflict", "too many scenes");
        scene_rec_t s = {};
        strlcpy(s.owner, session.user, sizeof(s.owner));
        if (const char *err = parse_scene(body, session, s)) return mesp_web_send_error(req, "400 Bad Request", err);
        s.id = s_next_id++;
        s_scenes[s_count++] = s;
        save();
        Json j;
        j.obj().key("id").num(s.id).end_obj();
        return mesp_web_send_json(req, j.out());
    }

    int idx = mesp_parse_u64(id_str, id) ? index_of(id) : -1;
    // Unknown and not visible look the same: don't reveal other people's scenes.
    if (idx < 0 || !can_run(session, s_scenes[idx])) {
        return mesp_web_send_error(req, "404 Not Found", "unknown scene");
    }
    if (op == "share") {
        if (session.role != MESP_ROLE_ADMIN) return mesp_web_send_error(req, "403 Forbidden", "admins only");
        std::string users;
        mesp_web_param(body, "users", users);
        if (const char *err = set_shares(s_scenes[idx].id, s_scenes[idx].owner, users)) {
            return mesp_web_send_error(req, "400 Bad Request", err);
        }
    } else if (!can_edit(session, s_scenes[idx])) {
        return mesp_web_send_error(req, "403 Forbidden", "only its owner may change this scene");
    } else if (op == "set") {
        scene_rec_t s = s_scenes[idx];
        if (const char *err = parse_scene(body, session, s)) return mesp_web_send_error(req, "400 Bad Request", err);
        s_scenes[idx] = s;
    } else if (op == "delete") {
        delete_at(idx);
    } else {
        return mesp_web_send_error(req, "400 Bad Request", "unknown op");
    }
    save();
    return mesp_web_send_json(req, "{\"ok\":true}");
}

void mesp_scenes_register_web()
{
    mesp_web_add("/api/scenes", HTTP_GET, scenes_get);
    mesp_web_add("/api/scenes", HTTP_POST, scenes_post);
}
